def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {v: sum(row.count(v) for row in grid) for v in set(x for row in grid for x in row)}
    bg = max(counts, key=counts.get)
    dots = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0}

    # Runs touching an edge cast perpendicular rays inward. The first cell
    # of each run is the anchor; following cells define the projected lanes.
    sides = [
        (0, range(w), lambda p: (1, 0), lambda p: (0, p)),
        (h - 1, range(w), lambda p: (-1, 0), lambda p: (h - 1, p)),
        (0, range(h), lambda p: (0, 1), lambda p: (p, 0)),
        (w - 1, range(h), lambda p: (0, -1), lambda p: (p, w - 1)),
    ]

    for edge, positions, direction, edge_coord in sides:
        pos = list(positions)
        i = 0
        while i < len(pos):
            r0, c0 = edge_coord(pos[i])
            if grid[r0][c0] == bg:
                i += 1
                continue
            j = i
            while j < len(pos):
                rr, cc = edge_coord(pos[j])
                if grid[rr][cc] == bg:
                    break
                j += 1
            dr, dc = direction(pos[i])
            for k in range(i + 1, j):
                rr, cc = edge_coord(pos[k])
                rr += dr
                cc += dc
                while 0 <= rr < h and 0 <= cc < w:
                    if (rr, cc) in dots:
                        out[rr][cc] = 4
                        break
                    if grid[rr][cc] == bg:
                        out[rr][cc] = 0
                    rr += dr
                    cc += dc
            i = j
    return out
